import React from 'react';
import { Message, COperationMenu } from '@cloud-materials/common';

export default () => {
  return (
    <div>
      <div>
        <h3>异步获取下拉菜单加载失败, 每次点击都重新加载</h3>
        <COperationMenu
          displayNum={4}
          defaultButtonType="secondary"
          operations={[
            {
              name: 'outline',
              disabled: true,
              tooltip: '当前状态下不可点击',
              arcoButtonProps: {
                type: 'outline',
              },
              onClick: () => {
                Message.info({ content: 'click' });
              },
            },
            {
              name: 'default',
              arcoPopconfirmProps: {
                title: '确定操作？',
                onOk: async () => {
                  await new Promise(rs => {
                    setTimeout(rs, 1000);
                  });
                  Message.info({ content: 'ok' });
                },
              },
            },
          ]}
          reloadOperationEachClick
          asyncOperations={async () => {
            await new Promise<void>(rs => {
              setTimeout(rs, 1000);
            });
            throw new Error('error');
            return [
              {
                name: '扩容',
                onClick: () => alert('扩容'),
              },
              {
                name: '缩容',
                onClick: () => alert('缩容'),
                subOperation: [
                  {
                    name: '更新',
                    onClick: () => alert('更新'),
                  },
                ],
              },
            ];
          }}
        />
        <h3>异步获取下拉菜单加载成功, 且只加载一次</h3>
        <COperationMenu
          defaultButtonType="secondary"
          asyncOperations={async () => {
            await new Promise<void>(rs => {
              setTimeout(rs, 1000);
            });
            return [
              {
                name: '扩容',
                onClick: () => alert('扩容'),
              },
              {
                name: '缩容',
                onClick: () => alert('缩容'),
                subOperation: [
                  {
                    name: '更新',
                    onClick: () => alert('更新'),
                  },
                ],
              },
            ];
          }}
        />
      </div>
    </div>
  );
};
